// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function _test(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v < c.MinDeposit());
        vm.assume(address(this).balance >= v);
        uint256 before;
        try c.balances(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        try c.Deposit{value: v}() {} catch { return; }
        assertTrue(c.balances(address(this)) == before);
    }

    function testFuzz_test(uint256 v) public {
        _test(v);
    }

    receive() external payable {}

    fallback() external payable {}
}
